/**
 * Public entry for `react-native-swiftshare-core`.
 *
 * The real implementation is generated by `ubrn build android --and-generate`
 * into ./generated/swiftshare_core.ts (+ swiftshare_core-ffi.ts,
 * NativeSwiftshareCore.ts). The old `declare`-only stubs compiled to nothing,
 * so `TransferEngine` was undefined at runtime. This entry now:
 *   1. installs the Rust JSI hostobject into globalThis.NativeSwiftshareCore
 *   2. initializes the generated bindings (checksums + callback vtables)
 *   3. re-exports the live classes/types from the generated bindings
 *
 * This file is hand-maintained (listed in ubrn.config.yaml noOverwrite).
 */
import installer from './generated/NativeSwiftshareCore';
import core from './generated/swiftshare_core';

let installed = false;
export function uniffiInit(): void {
  if (installed) return;
  installed = true;
  installer.installRustCrate();
  core.initialize();
}

// Sync flavor: initialize eagerly at import time, matching ubrn's generated
// index.tsx behavior. Safe because the TurboModule is available at bundle load.
uniffiInit();

// Re-export all live bindings (TransferEngine, Handshake, callbacks, ...).
export * from './generated/swiftshare_core';

/** Kept for API compatibility; sync init already happened at import. */
export async function uniffiInitAsync(): Promise<void> {
  /* no-op */
}
